 "content": "from collections import Counter

def transform(grid):
    # Each 3x3 patch represents one output cell. The dominant non-5
    # color in the patch is its encoded value; patches without one map to 0.
    h,w=len(grid),len(grid[0])
    out=[]
    for r in range(0,h,3):
        row=[]
        for c in range(0,w,3):
            counts=Counter(grid[y][x] for y in range(r,min(r+3,h))
                           for x in range(c,min(c+3,w)) if grid[y][x]!=5)
            row.append(counts.most_common(1)[0][0] if counts else 0)
        out.append(row)
    return out
